// The Map view of the quest log: a parchment world map you can drag and zoom, with quest markers
// on Bhutan and North Carolina. Picking a marker or a place card flies the map there.
// Map shapes come from js/mapdata.js (generated by tools/build-map.mjs) and load the first time the map opens.
import { places, quests } from "./content.js";
import { openQuest, onViewChange } from "./quests.js";
import { el, reduced } from "./dom.js";

const MAX_ZOOM = 12;
const ZOOM_AT = { bhutan: 9, nc: 5.5 }; // how close "fly to" goes for each place
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

const svg = (inner, viewBox, cls) => {
  const wrap = document.createElement("div");
  wrap.innerHTML = `<svg viewBox="${viewBox}" class="${cls}" aria-hidden="true">${inner}</svg>`;
  return wrap.firstChild;
};

function build(root, map) {
  const W = map.width, H = map.height;
  const stage = el("div", { class: "worldmap__stage" });
  const art = svg(
    `<g id="wm-world">
       <path class="wm__sea" d="${map.outline}"/>
       <path class="wm__grid" d="${map.graticule}"/>
       <path class="wm__land" d="${map.land}"/>
       <path class="wm__borders" d="${map.borders}"/>
       <path class="wm__home" d="${map.nc.shape}"/>
       <path class="wm__home" d="${map.bhutan.shape}"/>
       <path class="wm__route" id="wm-route" pathLength="1" d="${map.route}"/>
     </g>`,
    `0 0 ${W} ${H}`, "wm");
  stage.append(art);
  const world = art.querySelector("#wm-world");

  // ---- view state: screen = k * point + (tx, ty), in the SVG's own units ----
  const view = { k: 1, tx: 0, ty: 0 };
  const pins = {}, cardEls = {};
  function apply() {
    view.k = clamp(view.k, 1, MAX_ZOOM);
    view.tx = clamp(view.tx, W - W * view.k, 0);
    view.ty = clamp(view.ty, H - H * view.k, 0);
    world.setAttribute("transform", `translate(${view.tx.toFixed(2)} ${view.ty.toFixed(2)}) scale(${view.k.toFixed(4)})`);
    for (const [id, pin] of Object.entries(pins)) {
      const [px, py] = map[id].point;
      const x = (px * view.k + view.tx) / W, y = (py * view.k + view.ty) / H;
      pin.style.left = `${x * 100}%`;
      pin.style.top = `${y * 100}%`;
      pin.hidden = x < 0 || x > 1 || y < 0 || y > 1;
    }
    // at full view a vertical swipe should still scroll the page; once zoomed in, drags belong to the map
    art.style.setProperty("--k", view.k.toFixed(3));
    art.style.setProperty("--dash", (0.012 / view.k).toFixed(5));
    stage.style.touchAction = view.k > 1.01 ? "none" : "pan-y";
    stage.classList.toggle("is-zoomed", view.k > 1.01);
    zoomOut.disabled = reset.disabled = view.k <= 1.01;
    zoomIn.disabled = view.k >= MAX_ZOOM - 0.01;
  }
  // zoom by `factor`, keeping the map point under (cx, cy) fixed
  function zoomAt(factor, cx = W / 2, cy = H / 2) {
    const k = clamp(view.k * factor, 1, MAX_ZOOM);
    view.tx = cx - ((cx - view.tx) / view.k) * k;
    view.ty = cy - ((cy - view.ty) / view.k) * k;
    view.k = k;
    apply();
  }
  function flyTo(k, px, py) {
    const target = { k, tx: W / 2 - px * k, ty: H / 2 - py * k };
    if (window.gsap) gsap.killTweensOf(view);
    if (reduced || !window.gsap) { Object.assign(view, target); apply(); return; }
    gsap.to(view, { ...target, duration: 1.2, ease: "power2.inOut", onUpdate: apply });
  }
  const toMap = (e) => {
    const r = stage.getBoundingClientRect();
    return [((e.clientX - r.left) / r.width) * W, ((e.clientY - r.top) / r.height) * H];
  };

  // ---- controls ----
  const ctl = (label, text, fn) => {
    const b = el("button", { class: "wm__btn", type: "button", "aria-label": label, text });
    b.addEventListener("click", fn);
    return b;
  };
  const zoomIn = ctl("Zoom in", "+", () => zoomAt(1.6));
  const zoomOut = ctl("Zoom out", "−", () => zoomAt(1 / 1.6));
  const reset = ctl("Show the whole world", "World", () => flyTo(1, W / 2, H / 2));
  reset.classList.add("wm__btn--wide");
  stage.append(el("div", { class: "wm__controls" }, zoomIn, zoomOut, reset));

  // ---- drag to pan, pinch to zoom ----
  const active = new Map();
  let pinch = 0;
  stage.addEventListener("pointerdown", (e) => {
    if (e.target.closest("button")) return;
    if (window.gsap) gsap.killTweensOf(view);
    active.set(e.pointerId, toMap(e));
    stage.setPointerCapture(e.pointerId);
    if (active.size === 2) { const [a, b] = [...active.values()]; pinch = Math.hypot(a[0] - b[0], a[1] - b[1]); }
    stage.classList.add("is-dragging");
  });
  stage.addEventListener("pointermove", (e) => {
    if (!active.has(e.pointerId)) return;
    const prev = active.get(e.pointerId), now = toMap(e);
    active.set(e.pointerId, now);
    if (active.size === 1) {
      view.tx += now[0] - prev[0];
      view.ty += now[1] - prev[1];
      apply();
    } else if (active.size === 2) {
      const [a, b] = [...active.values()];
      const dist = Math.hypot(a[0] - b[0], a[1] - b[1]);
      if (pinch > 0) zoomAt(dist / pinch, (a[0] + b[0]) / 2, (a[1] + b[1]) / 2);
      pinch = dist;
    }
  });
  const release = (e) => { active.delete(e.pointerId); pinch = 0; if (!active.size) stage.classList.remove("is-dragging"); };
  stage.addEventListener("pointerup", release);
  stage.addEventListener("pointercancel", release);
  stage.addEventListener("dblclick", (e) => { if (!e.target.closest("button")) zoomAt(1.8, ...toMap(e)); });
  // trackpad pinch arrives as ctrl + wheel; a plain wheel is left alone so the page still scrolls
  stage.addEventListener("wheel", (e) => {
    if (!e.ctrlKey && !e.metaKey) return;
    e.preventDefault();
    zoomAt(Math.exp(-e.deltaY * 0.01), ...toMap(e));
  }, { passive: false });

  // ---- markers and place cards ----
  const cards = el("div", { class: "worldmap__places" });
  const select = (id, fly) => {
    for (const key of Object.keys(pins)) {
      pins[key].classList.toggle("is-active", key === id);
      cardEls[key].classList.toggle("is-active", key === id);
    }
    if (fly) flyTo(ZOOM_AT[id] || 5, ...map[id].point);
  };

  for (const place of places) {
    const geo = map[place.id];
    if (!geo) continue;
    const short = place.name.split(",")[0];

    // a real button placed over the map, so it works with keyboard and touch
    const pin = el("button", { class: `pin pin--${place.id}`, type: "button", "aria-label": `${place.name}: ${place.role}. Fly here.` },
      el("span", { class: "pin__gem", "aria-hidden": "true" }), el("span", { class: "pin__label", "aria-hidden": "true", text: short }));
    pin.addEventListener("click", () => select(place.id, true));
    pins[place.id] = pin;
    stage.append(pin);

    const here = place.quests.map((id) => quests.find((q) => q.id === id)).filter(Boolean);
    const fly = el("button", { class: "place__fly", type: "button", text: `Fly to ${short}` });
    fly.addEventListener("click", () => {
      select(place.id, true);
      stage.scrollIntoView({ block: "nearest", behavior: reduced ? "auto" : "smooth" });
    });
    const card = el("article", { class: "place" },
      svg(`<path d="${geo.inset}"/>${geo.insetPoint ? `<rect class="place__dot" x="${geo.insetPoint[0] - 4}" y="${geo.insetPoint[1] - 4}" width="8" height="8" transform="rotate(45 ${geo.insetPoint[0]} ${geo.insetPoint[1]})"/>` : ""}`, "0 0 150 90", "place__shape"),
      el("div", { class: "place__body" },
        el("p", { class: "place__role", text: place.role }),
        el("h3", { class: "place__name", text: place.name }),
        el("p", { text: place.text }),
        here.length ? el("ul", { class: "place__quests" }, ...here.map((q) => {
          const b = el("button", { type: "button", text: q.title });
          b.addEventListener("click", () => openQuest(q.id));
          return el("li", {}, b);
        })) : null,
        fly));
    cardEls[place.id] = card;
    cards.append(card);
  }

  root.append(
    stage,
    el("p", { class: "worldmap__hint", text: "Drag to move the map. Zoom with the buttons, a pinch, or a double click. Pick a marker to fly there." }),
    cards);
  select("nc", false);
  apply();

  // the flight path draws itself once
  if (!reduced && window.gsap) {
    const route = root.querySelector("#wm-route");
    gsap.fromTo(route, { strokeDasharray: 1, strokeDashoffset: 1 }, {
      strokeDashoffset: 0, duration: 1.6, ease: "power2.inOut",
      onComplete: () => { route.style.strokeDasharray = ""; route.style.strokeDashoffset = ""; },
    });
    gsap.from(root.querySelectorAll(".pin__gem"), { scale: 0, rotate: 45, duration: 0.5, ease: "back.out(2)", stagger: 0.9, delay: 0.1, clearProps: "transform" });
  }
}

export function initMap() {
  const root = document.getElementById("view-map");
  let started = false;
  onViewChange(async (name) => {
    if (name !== "map" || started) return;
    started = true;
    root.append(el("p", { class: "worldmap__hint", id: "wm-loading", text: "Unrolling the map..." }));
    try {
      const { map } = await import("./mapdata.js");
      root.replaceChildren();
      build(root, map);
    } catch (err) {
      console.error("[site] map failed to load", err);
      root.replaceChildren(el("p", { class: "worldmap__hint", text: "The map could not load. Reload the page to try again." }));
      started = false;
    }
  });
}
